'eng.rules' => 'Completato % = (peso dei deliverable completati + ore registrate su lavori aperti, con tetto) ÷ (budget + extra approvate). Utilizzato % = registrate ÷ budget — oltre il 100 % la sezione supera il budget concordato; la parte tratteggiata della barra è l\'extra approvato. Al 90 % delle ore consentite la sezione diventa ambra; oltre tale soglia è superata e le nuove ore engineering vengono bloccate finché non vengono approvate ore extra o la sezione non viene dichiarata conclusa.',
