'eng.sec_add' => 'Aggiungi sezione',
'eng.sec_hint' => 'Le sezioni ritirate scompaiono dalle schede ma conservano la loro storia. Rinomina invece di eliminare.',
'eng.sec_need' => 'Codice (lettere / cifre, massimo 12) e nome sono obbligatori.',
'eng.need_r47' => 'Esegui prima install/migrate_cp_r47_engineering.sql e install/migrate_cp_r47b_eng_sections.sql.',
'eng.no_budget_yet' => 'Nessuna ora engineering ancora a budget (revisione budget {r}). Inserisci le ore delle discipline engineering in Budget e consuntivo — le sezioni le leggono da lì.',
