'hr.ecd_training_auto' => 'calcolato dai corsi frequentati quest\'anno (numero e ore) in classifica tra i colleghi: primo 20 % = 5, successivo 20 % = 4, successivo 30 % = 3, resto = 2, nessuno = 1.',
'hr.ecd_attendance_auto' => 'calcolato dall\'anno: parte da 5; −1 ogni 16 h di uscite anticipate / ritardi, −1 ogni 3 giorni di assenza non pianificata (non retribuita, altra assenza — la malattia è mostrata ma non penalizzata), −1 ogni 3 richieste di ferie chieste con meno di 2 giorni di anticipo. In / Out: una costanza (giorni con In e Out completi ÷ giorni lavorativi attesi, ferie approvate escluse) sotto il 90 % costa −1 per ogni decina di punti percentuali iniziata, al massimo −3; non valutata prima di 20 giorni attesi.',
