'hra.welcome_title' => 'Ciao {n}',
'hra.welcome_1' => 'Questo assistente raccoglie i dati della tua scheda dipendente in sei brevi passi. Ogni campo è precompilato con quanto HR possiede oggi: confermalo, correggilo o lascialo. Puoi fermarti quando vuoi e continuare più tardi — anche dal telefono.',
'hra.privacy_title' => 'Come trattiamo i tuoi dati',
'hra.privacy_1' => 'Titolare: Golden Automation Systems (Sistimata Ischyos ATEE), Kiou 5, Keratsini — per la filiale italiana GOLDEN AS ITALIAN. Finalità: tenuta del fascicolo del personale richiesto dal diritto del lavoro, previdenziale e fiscale, e contatto con te o con la persona di emergenza. Base giuridica: il contratto di lavoro e gli obblighi di legge del datore di lavoro.',
'hra.privacy_2' => 'Quanto inserisci qui resta in un\'area provvisoria fino all\'approvazione di HR; i numeri identificativi (AMKA, codice fiscale, carta d\'identità, passaporto, IBAN) vi sono cifrati e leggibili solo da HR. Destinatari: HR, l\'Owner e, per le paghe, il consulente / commercialista. Conservazione: i dati provvisori sono cancellati 90 giorni dopo la decisione; la scheda segue la conservazione del fascicolo del personale.',
'hra.privacy_3' => 'I tuoi diritti: accesso, rettifica (tramite questo assistente), cancellazione e limitazione dove la legge lo consente, e reclamo al Garante per la protezione dei dati personali. Domande: HR › Messaggi con HR.',
