'et.d_b_rfq' => "Spettabile ditta,\n\nin allegato {doc}. Vi preghiamo di quotare miglior prezzo, tempo di consegna, validità e condizioni di pagamento per riga, indicando costruttore, tipo e paese d'origine, e di inviare l'offerta entro la data indicata sul documento citando il nostro numero.\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_s_po_chase' => "Ordine {no} — stato della consegna",
'et.d_b_po_chase' => "Spettabile ditta,\n\ncon riferimento a {doc}, vi chiediamo di confermare lo stato del nostro ordine: merce pronta alla spedizione, data di spedizione, spedizioniere e riferimento di tracciamento, nonché gli articoli ancora in sospeso con la data prevista.\n\nLa consegna è legata al programma di una nave; vi preghiamo di segnalarci subito ogni ritardo.\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_s_ncr' => "Non conformità sull'ordine {no}",
'et.d_b_ncr' => "Spettabile ditta,\n\nal ricevimento della merce di {doc} abbiamo rilevato le non conformità descritte nel rapporto allegato (quantità, danni o scostamenti dall'ordine). Vi preghiamo di confermare entro tre giorni lavorativi come intendete risolverle — sostituzione, nota di credito o riparazione — e la data.\n\nGli articoli non conformi sono trattenuti nel nostro magazzino a vostra disposizione.\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_s_remittance' => "Avviso di pagamento — {branch}",
'et.d_s_sup_statement' => "Estratto conto — {branch}",
'et.d_b_remittance' => "Spettabile ditta,\n\nin allegato il nostro avviso di pagamento per {doc}. L'importo è stato bonificato sul conto indicato nella vostra fattura; vi preghiamo di imputarlo alle fatture elencate e di inviarci la quietanza.\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_b_sup_statement' => "Gentili Signori,\n\nin allegato il {doc} come risulta dai nostri libri. Vi preghiamo di verificarlo con le vostre registrazioni e di segnalarci eventuali differenze.\n\nCordiali saluti,\n{user}\n{branch}",
