'em.find_ph' => "Cerca una persona nei Contatti — nome, e-mail o azienda…",
'si.w_invoice' => 'la vostra fattura {no}',
'sup.ct_all' => 'Tutti i contatti',
'sup.ct_none' => 'Nessuna persona — aggiungine una o importale con il foglio Contacts dell\'import ERP.',
