'jd.g_equal' => 'Golden A/S non discrimina per età, colore, disabilità, origine etnica o nazionale, genere o riassegnazione di genere, cultura, salute, stato civile, sociale o economico, razza, credo religioso o assenza di credo, responsabilità verso persone a carico, sessualità, appartenenza sindacale o orario di lavoro. Ogni dipendente rispetta questa politica nello svolgimento delle proprie mansioni.',
'jd.g_hs_t' => 'Salute e sicurezza sul lavoro',
'jd.g_hs' => 'Ogni dipendente presta ragionevole cura per evitare lesioni a sé e ad altri nel proprio lavoro, osserva le regole di salute e sicurezza dell\'azienda, del cantiere e della nave e collabora con l\'azienda nell\'adempimento degli obblighi di legge.',
'jd.g_conf_t' => 'Riservatezza',
'jd.g_conf' => 'Il titolare della posizione mantiene riservati i materiali e le informazioni sensibili dell\'azienda, dei clienti e delle loro navi, pur incoraggiando l\'apertura e la segnalazione di problemi.',
'jd.g_data_t' => 'Protezione dei dati',
'jd.g_data' => 'I dati personali sono trattati secondo il Regolamento generale sulla protezione dei dati (UE) 2016/679 e la normativa nazionale applicabile. La divulgazione non autorizzata di dati personali può avere conseguenze legali per l\'azienda e per il responsabile.',
