'et.d_s_rc_general' => "La sua candidatura {no} — {title} — Golden A/S",
'et.d_s_rc_shortlisted' => "La sua candidatura per {title} — prossimo passo — Golden A/S",
'et.d_s_rc_interview' => "Invito al colloquio — {title} — Golden A/S",
'et.d_s_rc_offer' => "Offerta — {title} — Golden A/S",
'et.d_s_rc_rejected' => "La sua candidatura per {title} — Golden A/S",
'et.d_b_rc_general' => "Gentile {name},\n\nla ringraziamo per la sua candidatura {no} per la posizione di {title} ({doc}).\n\n\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_b_rc_shortlisted' => "Gentile {name},\n\nla ringraziamo per la sua candidatura per la posizione di {title}. L'abbiamo esaminata con interesse e desideriamo invitarla alla fase successiva del nostro processo di selezione.\n\nLa contatteremo a breve per concordare un orario. Nel frattempo la preghiamo di segnalarci eventuali cambiamenti nella sua disponibilità.\n\nCordiali saluti,\n{user}\n{branch}",
'et.d_b_rc_interview' => "Gentile {name},\n\na seguito della sua candidatura per la posizione di {title}, desideriamo invitarla a un colloquio.\n\nData e ora: {when}\nDurata: {duration}\nModalità / luogo: {mode}\nIntervistatori: {interviewers}\n\nLa preghiamo di confermare che l'orario proposto le sia comodo o di proporre un'alternativa.\n\n{signature}",
'et.d_b_rc_offer' => "Gentile {name},\n\nsiamo lieti di comunicarle che, al termine del processo di selezione, desideriamo offrirle la posizione di {title}.\n\nLa nostra proposta:\n\nRetribuzione netta: {salary}\nContratto: {contract}\nData di inizio: {start}\nOrario di lavoro: {hours}\nSede di lavoro: {place}\nPeriodo di prova: {probation}\nBenefit: {benefits}\nAltre condizioni: {terms}\nOfferta valida fino al: {valid}\n\nRiceverà una e-mail separata da Golden A/S con un link personale, dove accetta l’offerta e la data di inizio. Se desidera prima discutere un punto, risponda a questa e-mail. Saremo lieti di accoglierla nel team.\n\nDescrizione della posizione\n----------------------------------------\n{jd}\n\n{signature}",
'et.d_b_rc_rejected' => "Gentile {name},\n\nla ringraziamo per la sua candidatura per la posizione di {title} e per il tempo dedicato al nostro processo di selezione.\n\nDopo attenta valutazione abbiamo deciso di proseguire con altri candidati il cui profilo è più vicino ai requisiti di questo ruolo. Conserveremo i suoi dati per sei mesi e la contatteremo qualora si aprisse una posizione adatta.\n\nLe auguriamo ogni successo.\n\nCordiali saluti,\n{user}\n{branch}",
'rc.key_once_hint' => 'Copiala ora nel secret PORTAL_RC_KEY (o PORTAL_STATS_KEY) del repository del sito — al prossimo caricamento è mascherata.',
// R91-003 outgoing mail
'web.mail' => 'Posta in uscita',
'web.mail_smtp' => 'SMTP autenticato via {host} come {user}: i messaggi a candidati, HR e dal sito superano SPF/DMARC.',
'web.mail_phpmail' => 'PHP mail(): SMTP non configurato. La posta goldenas.com.gr è su Microsoft 365 e il suo SPF rifiuta altri mittenti: i messaggi finiranno nella posta indesiderata.',
'web.mail_hint' => 'Preferito: Microsoft Graph con OAuth2 client credentials — imposta il blocco graph in customer/app/config.php (tenant, client_id, client_secret, from) da una registrazione app Entra con permesso applicativo Mail.Send, limitata alla casella mittente da una application access policy; nessuna password di casella viene salvata. Ripiego: il blocco smtp (smtp.office365.com:587, casella con "Authenticated SMTP" e app password). Il sito usa gli stessi valori nel suo api/config.php.',
// R91-004 CV retention controls
'rc.pool_retention' => 'Conservazione talent pool (mesi)',
'rc.pool_retention_hint' => 'Le iscrizioni al talent pool si basano sul consenso del candidato e possono durare più delle candidature; vengono cancellate dopo questo periodo.',
'rc.keep_title' => 'Conservazione di questa candidatura',
'rc.keep_hint' => 'Le candidature non andate a buon fine e il relativo CV vengono cancellati automaticamente {months} mesi dopo l’ultimo cambio di stato. Conservala più a lungo solo con un motivo documentato: consenso del candidato a restare disponibile per ruoli futuri, o processo in corso.',
