'io.c_title' => 'Entrata / Uscita — registrazione di ora e posizione',
'io.c_text' => "Golden A/S registra l'ora e la posizione del tuo telefono nel momento in cui timbri l'entrata e nel momento in cui timbri l'uscita, insieme al sito aziendale più vicino, alla precisione della posizione e all'app o al computer usato. La posizione non viene seguita nel frattempo.\n\nI dati servono a confermare la presenza sul luogo di lavoro, l'orario di lavoro e gli straordinari. Sono confrontati con il foglio ore e con i rapporti di servizio e sono considerati nella valutazione del personale (costanza e precisione).\n\nLe tue timbrature sono viste da HR, dalla direzione, dal tuo responsabile e dai project manager; le statistiche solo da HR, dal CEO e dal Direttore Generale. Vedi le tue timbrature nell'app e sul portale.\n\nInformativa sulla privacy: https://www.goldenas.com.gr/privacy.html",
