'io.fl_steps' => 'I passi a parole',
'io.fl_p1' => 'Informativa. La prima volta che usa In / Out legge l\'informativa sulla registrazione di ora e posizione e la accetta — una volta, nell\'app o sul portale. L\'accettazione viene scritta nel Suo registro HR. Senza di essa nessuna registrazione è possibile.',
'io.fl_p2' => 'In. Quando inizia il lavoro preme In. L\'app registra l\'ora, la posizione del telefono in quel momento e la sede aziendale più vicina. Sul portale In / Out funziona solo da un indirizzo di rete registrato di una sede aziendale. La Sua posizione non viene seguita tra In e Out.',
'io.fl_p3' => 'Controllo automatico. Ogni registrazione viene controllata subito: è dentro una sede nota, dentro l\'orario di lavoro (fino a {t} minuti dopo l\'inizio vale ancora come puntuale) e la posizione è affidabile. Una registrazione in ordine viene accettata automaticamente. Una registrazione con un\'osservazione — fuori sede, in ritardo, in anticipo, posizione debole o mancante, Out senza In, doppia registrazione — è un\'eccezione: attende sotto «Da decidere» finché il Suo responsabile, un project manager o HR la approva o la rifiuta con una nota.',
'io.fl_p4' => 'Out. Quando termina il lavoro preme Out. Passa lo stesso controllo dell\'In. Sono ammesse più coppie In / Out nello stesso giorno (per esempio una visita a una nave e il ritorno in ufficio).',
'io.fl_p5' => 'Risultato del giorno. Il portale somma il tempo tra ogni In e il suo Out. In un giorno lavorativo di cinque ore o più viene tolta la pausa del Suo calendario orario. Ciò che supera le ore previste è straordinario, quando è di almeno {o} minuti; tutto il tempo in un giorno non lavorativo è straordinario.',
'io.fl_p6' => 'Controllo incrociato. Il tempo netto del giorno viene confrontato con le ore registrate nel timesheet e con il tempo di lavoro (WT) dei rapporti di servizio dello stesso giorno. Una differenza oltre {m} minuti rispetto al timesheet in un senso o nell\'altro, o più tempo di lavoro nei rapporti di servizio di quanto mostri la presenza, viene segnalata sotto «Straordinari e riscontro» perché si corregga il timesheet, il rapporto o la registrazione.',
'io.fl_p7' => 'Decisione sullo straordinario. Lo straordinario non è accettato da solo. Chi decide sulle Sue registrazioni lo approva o lo rifiuta per giorno, con una nota. Le registrazioni rifiutate non contano nel risultato del giorno.',
'io.fl_p8' => 'Statistiche. Per ogni persona HR, il CEO e il Direttore Generale vedono tre valori per periodo: costanza (giorni lavorativi con In e Out completi), accuratezza (registrazioni senza osservazioni) e puntualità (primo In del giorno entro la tolleranza).',
'io.fl_p9' => 'Valutazione del personale. La costanza dell\'anno fa parte del voto calcolato «Presenza e costanza» della valutazione annuale; accuratezza e puntualità sono mostrate accanto, al valutatore e a Lei su My HR.',
'io.fl_ev_h' => 'Collegamento con la valutazione del personale',
'io.fl_ev_p1' => 'La valutazione annuale ha due criteri calcolati dal portale. «Presenza e costanza» parte da 5 e perde punti per uscite anticipate e arrivi in ritardo, assenze non pianificate e ferie chieste all\'ultimo momento (dalle richieste HR approvate dell\'anno) e per la costanza di In / Out.',
'io.fl_ev_p2' => 'Costanza In / Out = giorni con In e Out completi ÷ giorni attesi. I giorni attesi sono i giorni lavorativi del Suo calendario dalla prima registrazione dell\'anno a oggi; i giorni di ferie, malattia o assenza approvata senza registrazione sono esclusi. Dal 90 % non si detrae nulla; sotto, un punto per ogni decina di punti percentuali iniziata (80–89 %: −1, 70–79 %: −2, meno: −3). Con meno di 20 giorni attesi il valore è mostrato e non ancora valutato. La percentuale della prima soglia si imposta in Sedi e regole.',
'io.fl_ev_p3' => 'Accuratezza e puntualità sono mostrate sotto il criterio e non cambiano il voto. Vede i Suoi valori su My HR › Come ti valutiamo.',
'io.ev_txt' => 'In / Out dell\'anno: costanza {c} ({d} di {w} giorni attesi; {x} giorno/i di ferie o assenza approvata esclusi) · accuratezza {a} · puntualità {p} — {s}',
