'pdc.xl_tpl' => 'Modello Excel',
'pdc.xl_lede' => 'Excel: quando avete le righe del documento come elenco, compilate il modello (Code e Qty obbligatori) e caricatelo al posto della scansione. Le righe sono prese esattamente come scritte e abbinate all ordine per codice — il nostro codice, il codice del costruttore o un codice memorizzato per questo fornitore. Solo le righe con un codice che non è nell ordine vengono sottoposte all assistente.',
'pdc.xl_only' => 'Un file Excel nel formato del modello può comunque essere controllato: viene abbinato per codice, senza l assistente.',
'pdc.xl_hint' => 'Excel (.xlsx) nel formato del modello, fino a 2 MB e 300 righe. Un documento per controllo.',
'pdc.xl_bad' => 'Il file non è una cartella Excel (.xlsx) leggibile. Salvatelo di nuovo da Excel come .xlsx.',
'pdc.xl_no_cols' => 'Le colonne Code e Qty non sono state trovate nelle prime 15 righe del primo foglio. Usate il modello Excel.',
