'pdc.xl_many' => 'Il file ha più di {n} righe. Dividetelo in più file.',
'pdc.xl_other_po' => 'Il file è per l ordine {a}; questo è l ordine {b}. Aprite l ordine giusto o correggete la colonna PO No.',
