'pdc.xl_r_part' => 'Codice del costruttore della riga {n} dell ordine.',
'pdc.xl_r_alias' => 'Codice già usato da questo fornitore per la riga {n}.',
'pdc.xl_r_line' => 'La riga {n} è indicata nel file; il codice è diverso da quello della riga.',
'pdc.xl_r_shared' => 'Il codice è su più righe dell ordine — controllare la riga.',
'pdc.xl_r_none' => 'Questo codice non è nell ordine.',
'pdc.xl_note' => 'File Excel: {n} righe · {m} abbinate per codice · {a} abbinate dall assistente · {x} non nell ordine.',
'pdc.xl_skipped' => '{n} righe senza quantità maggiore di zero sono state escluse.',
'pdc.xl_no_ask' => 'Le righe non presenti nell ordine non sono state sottoposte all assistente (spento, limite raggiunto o nessuna risposta) — controllatele a mano.',
'pdc.xl_reading_h' => 'Il file viene confrontato con l ordine',
'pdc.xl_reading' => 'Le righe del file vengono abbinate all ordine per codice. Occorrono pochi secondi; di più solo quando righe non presenti nell ordine vengono sottoposte all assistente. La pagina si aggiorna da sola.',
'pdc.xl_tpl_title' => 'Documento di consegna in Excel — come compilarlo',
'pdc.xl_tpl_n0' => 'Per l ordine di acquisto {po}. Una riga per ogni riga del documento del fornitore, nel primo foglio, intestazioni nella riga 1. Caricarlo nell ordine › Controllo consegna.',
'pdc.xl_tpl_n1' => 'Code (obbligatorio): il codice come stampato sul documento. Viene confrontato con il nostro codice, il codice del costruttore della riga d ordine e i codici memorizzati per questo fornitore; maiuscole, spazi, punti e trattini non contano.',
'pdc.xl_tpl_n2' => 'Qty (obbligatorio): la quantità consegnata, maggiore di zero. Le righe senza quantità vengono escluse e contate.',
'pdc.xl_tpl_n3' => 'Description e Unit: come stampati. Servono quando occorre creare un nuovo articolo di magazzino o una nuova riga d ordine.',
'pdc.xl_tpl_n4' => 'Prezzi (possono restare vuoti): Unit price e Discount % del documento, oppure Net unit price, oppure Net value della riga. Si conserva il prezzo unitario netto: Net unit price, altrimenti Unit price meno lo sconto, altrimenti Net value ÷ Qty.',
'pdc.xl_tpl_n5' => 'Document No, Document date (gg/mm/aaaa) e Document type (invoice o delivery note): vale la prima riga compilata. PO No: se compilato deve essere {po} — un file di un altro ordine viene rifiutato.',
'pdc.xl_tpl_n6' => 'PO line (facoltativo): il numero della riga d ordine a cui appartiene la riga. Usatelo quando lo stesso codice è su più righe, o per componenti consegnati al posto di un assieme (più righe con la stessa riga d ordine).',
'pdc.xl_tpl_n7' => 'Fino a {max} righe e 2 MB. Niente formule, totali o celle unite; lo stesso codice può comparire su più righe. Sono accettate anche le intestazioni greche del documento: Κωδικός, Περιγραφή, Ποσότητα, Μ.Μ., Τιμή, Εκπτ.%, Καθαρή αξία.',
